+
+   /**
+    * Ensures that a path is safe to use as a target for writing content
+    * based on a name from an untrusted source. Primarily this involves
+    * ensuring that the path cannot be constructed to target a directory
+    * via a relative path or drive letter.
+    * Note that the path separator in the resulting path will
+    * always be the Unix separator.
+    *
+    * @param path path to validate
+    * @return normalized path or an empty string if the path is not valid
+    */
+   public static String normalizePath(String path)
+   {
+      // fail if we have invalid path separators
+      if (path == null || path.isEmpty() || !isValidPathSeparator(path))
+      {
+         return "";
+      }
+
+      // replace all separators with the unix separator
+      for (char c : SEPARATORS)
+      {
+         path = path.replace(c, '/');
+      }
+
+      List<String> components = new ArrayList<>();
+      for (String component : path.split("/"))
+      {
+         // ignore empty components or current directory components
+         if (component.isEmpty() || ".".equals(component))
+         {
+            continue;
+         }
+
+         // if we hit a parent directory component, remove the last item we added
+         // if we don't have any items we have an invalid path
+         if ("..".equals(component))
+         {
+            if (components.isEmpty())
+            {
+               return "";
+            }
+            components.remove(components.size() - 1);
+            continue;
+         }
+
+         // just ignore a Windows drive letter
+         if (component.length() > 1 && component.charAt(1) == ':')
+         {
+            continue;
+         }
+
+         components.add(component);
+      }
+
+      return String.join("/", components);
+   }
+
+   /**
+    * Returns true if the path contains a valid separator.
+    * The first separator found in the path is noted,
+    * any other separators are invalid.
+    *
+    * @param path path to validate
+    * @return true if the path contains a valid separator
+    */
+   private static boolean isValidPathSeparator(String path)
+   {
+      // check for separator left of the current one
+      for (int index = 1; index < SEPARATORS.length; index++)
+      {
+         if (path.indexOf(SEPARATORS[index]) != -1 && path.indexOf(SEPARATORS[index - 1]) != -1)
+         {
+            return false;
+         }
+      }
+      return true;
+   }
 }
